from __future__ import annotations; from datetime import date; from decimal import Decimal; import pytest; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession; from src.pricing import FxWarning, PrefetchedFxRates; from src.pricing.base.errors import NoObservationError, PricingError; from src.pricing.extension.fx import get_average_rate, get_exchange_rate; from src.pricing.orm.market_data import FxRate; pytestmark = pytest.mark.asyncio
async def test_identity_rate_never_touches_the_database(db: AsyncSession): rate = await get_exchange_rate(db, 'sgd', 'SGD', date(2026, 6, 1)); assert rate == Decimal('1')
async def test_resolves_the_most_recent_rate_on_or_before_the_date(db: AsyncSession): db.add_all([FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.30'), rate_date=date(2026, 1, 1), source='test'), FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.35'), rate_date=date(2026, 6, 1), source='test')]); await db.commit(); rate = await get_exchange_rate(db, 'USD', 'SGD', date(2026, 6, 15)); assert rate == Decimal('1.35')
async def test_raises_no_observation_error_when_no_rate_exists(db: AsyncSession):
    with pytest.raises(NoObservationError): await get_exchange_rate(db, 'USD', 'SGD', date(2026, 6, 1))
async def test_lazy_load_derives_and_persists_the_inverse_rate(db: AsyncSession): db.add(FxRate(base_currency='SGD', quote_currency='HKD', rate=Decimal('5.800000'), rate_date=date(2026, 6, 30), source='test')); await db.commit(); rate = await get_exchange_rate(db, 'HKD', 'SGD', date(2026, 6, 30), lazy_load=True); assert rate == Decimal('0.172414'); persisted = await db.execute(select(FxRate).where(FxRate.base_currency == 'HKD', FxRate.quote_currency == 'SGD', FxRate.rate_date == date(2026, 6, 30))); derived = persisted.scalar_one(); assert derived.rate == Decimal('0.172414'); assert derived.source == 'derived:inverse:SGD/HKD'
async def test_lazy_load_still_raises_when_the_fallback_finds_nothing(db: AsyncSession):
    with pytest.raises(NoObservationError): await get_exchange_rate(db, 'HKD', 'SGD', date(2026, 6, 30), lazy_load=True)
async def test_average_rate_identity_never_touches_the_database(db: AsyncSession): rate = await get_average_rate(db, 'SGD', 'sgd', date(2026, 1, 1), date(2026, 6, 1)); assert rate == Decimal('1')
async def test_average_rate_rejects_an_inverted_range(db: AsyncSession):
    with pytest.raises(PricingError): await get_average_rate(db, 'USD', 'SGD', date(2026, 6, 1), date(2026, 1, 1))
async def test_average_rate_averages_observations_within_the_range(db: AsyncSession): db.add_all([FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.30'), rate_date=date(2026, 6, 1), source='test'), FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.40'), rate_date=date(2026, 6, 15), source='test'), FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('0.10'), rate_date=date(2026, 1, 1), source='test')]); await db.commit(); rate = await get_average_rate(db, 'USD', 'SGD', date(2026, 6, 1), date(2026, 6, 30)); assert rate == Decimal('1.35')
async def test_average_rate_falls_back_to_period_end_spot_rate_when_range_is_empty(db: AsyncSession): db.add(FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.35'), rate_date=date(2026, 1, 1), source='test')); await db.commit(); rate = await get_average_rate(db, 'USD', 'SGD', date(2026, 6, 1), date(2026, 6, 30)); assert rate == Decimal('1.35')
async def test_AC_pricing_fx_1_average_rate_fallback_appends_fx_warning(db: AsyncSession): 'AC-pricing.fx.1'; db.add(FxRate(base_currency='EUR', quote_currency='SGD', rate=Decimal('1.50'), rate_date=date(2025, 12, 31), source='test')); await db.commit(); warnings: list[FxWarning] = []; rate = await get_average_rate(db, 'EUR', 'SGD', date(2026, 1, 1), date(2026, 1, 31), fx_warnings=warnings); assert rate == Decimal('1.50'); assert warnings == [{'type': 'average_rate_fallback', 'base_currency': 'EUR', 'quote_currency': 'SGD', 'start_date': '2026-01-01', 'end_date': '2026-01-31'}]
async def test_AC_pricing_fx_1_no_warning_when_rates_exist_in_range(db: AsyncSession): 'AC-pricing.fx.1'; db.add(FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.30'), rate_date=date(2026, 2, 15), source='test')); await db.commit(); warnings: list[FxWarning] = []; rate = await get_average_rate(db, 'USD', 'SGD', date(2026, 2, 1), date(2026, 2, 28), fx_warnings=warnings); assert rate == Decimal('1.30'); assert warnings == []
async def test_AC_pricing_fx_1_duplicate_fallback_warning_is_not_appended_twice(db: AsyncSession): 'AC-pricing.fx.1'; db.add(FxRate(base_currency='EUR', quote_currency='SGD', rate=Decimal('1.50'), rate_date=date(2025, 12, 31), source='test')); await db.commit(); warnings: list[FxWarning] = []; await get_average_rate(db, 'EUR', 'SGD', date(2026, 1, 1), date(2026, 1, 31), fx_warnings=warnings); await get_average_rate(db, 'EUR', 'SGD', date(2026, 1, 1), date(2026, 1, 31), fx_warnings=warnings); assert len(warnings) == 1
async def test_AC_pricing_fx_2_prefetch_serves_spot_and_average_keys(db: AsyncSession): 'AC-pricing.fx.2'; db.add_all([FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.30'), rate_date=date(2026, 6, 1), source='test'), FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.40'), rate_date=date(2026, 6, 15), source='test')]); await db.commit(); prefetched = PrefetchedFxRates(); await prefetched.prefetch(db, [('USD', 'SGD', date(2026, 6, 15), None, None), ('USD', 'SGD', date(2026, 6, 30), date(2026, 6, 1), date(2026, 6, 30))]); assert prefetched.get_rate('USD', 'SGD', date(2026, 6, 15)) == Decimal('1.40'); assert prefetched.get_rate('USD', 'SGD', date(2026, 6, 30), date(2026, 6, 1), date(2026, 6, 30)) == Decimal('1.35'); assert prefetched.get_rate('SGD', 'sgd', date(2026, 6, 15)) == Decimal('1'); assert prefetched.get_rate('GBP', 'USD', date(2026, 6, 15)) is None
async def test_AC_pricing_fx_2_prefetch_propagates_pricing_error(db: AsyncSession):
    'AC-pricing.fx.2'; prefetched = PrefetchedFxRates()
    with pytest.raises(PricingError): await prefetched.prefetch(db, [('USD', 'SGD', date(2026, 6, 15), None, None)])
async def test_AC_pricing_fx_2_prefetch_empty_pairs_is_a_noop(db: AsyncSession): 'AC-pricing.fx.2'; prefetched = PrefetchedFxRates(); await prefetched.prefetch(db, []); assert prefetched.get_rate('USD', 'SGD', date(2026, 6, 15)) is None
async def test_AC_pricing_fx_4_rate_series_equals_one_lookup_per_date(db: AsyncSession, monkeypatch):
    'AC-pricing.fx.4'; from src.pricing.extension import fx; from src.pricing.extension.fx import get_exchange_rate_series; db.add_all([FxRate(base_currency='SGD', quote_currency='HKD', rate=Decimal('5.800000'), rate_date=date(2026, 6, 1), source='test'), FxRate(base_currency='HKD', quote_currency='SGD', rate=Decimal('0.171100'), rate_date=date(2026, 6, 10), source='test'), FxRate(base_currency='HKD', quote_currency='SGD', rate=Decimal('0.173300'), rate_date=date(2026, 6, 20), source='test')]); await db.commit(); dates = [date(2026, 6, day) for day in range(1, 31)]; without_fallback = await get_exchange_rate_series(db, 'HKD', 'SGD', dates); assert sorted(without_fallback) == dates[9:]; candidate_reads = []; original_candidates = fx.SqlObservationRepository.candidates
    async def counting_candidates(self, subject, as_of, user_id=None): candidate_reads.append(as_of); return await original_candidates(self, subject, as_of, user_id)
    monkeypatch.setattr(fx.SqlObservationRepository, 'candidates', counting_candidates); covered_only = await get_exchange_rate_series(db, 'HKD', 'SGD', dates[9:]); assert candidate_reads == [date(2026, 6, 30)]; assert covered_only == without_fallback; series = await get_exchange_rate_series(db, 'HKD', 'SGD', dates, lazy_load=True); expected = {as_of: await get_exchange_rate(db, 'HKD', 'SGD', as_of, lazy_load=True) for as_of in dates}; assert series == expected; assert series[date(2026, 6, 5)] == Decimal('0.172414'); assert series[date(2026, 6, 15)] == Decimal('0.171100'); assert await get_exchange_rate_series(db, 'sgd', 'SGD', dates[:2]) == dict.fromkeys(dates[:2], Decimal('1'))
async def test_AC_pricing_fx_6_derived_inverse_rate_does_not_shadow_newer_inverse_rate(db: AsyncSession) -> None: 'AC-pricing.fx.6'; from src.pricing.extension.fx import get_exchange_rate_series; db.add_all([FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.200000'), rate_date=date(2025, 1, 10), source='manual'), FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.250000'), rate_date=date(2025, 1, 20), source='manual')]); await db.commit(); early_rate = await get_exchange_rate(db, 'SGD', 'CNY', date(2025, 1, 15), lazy_load=True); assert early_rate == Decimal('5.000000'); later_rate = await get_exchange_rate(db, 'SGD', 'CNY', date(2025, 1, 25), lazy_load=True); assert later_rate == Decimal('4.000000'); db.add(FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.500000'), rate_date=date(2025, 1, 28), source='manual')); await db.commit(); series = await get_exchange_rate_series(db, 'SGD', 'CNY', [date(2025, 1, 15), date(2025, 1, 25), date(2025, 1, 30)], lazy_load=True); assert series == {date(2025, 1, 15): Decimal('5.000000'), date(2025, 1, 25): Decimal('4.000000'), date(2025, 1, 30): Decimal('2.000000')}
